/** WebGL2 scene consumer for SLAI SGEO geometry primitives.
 *
 * Verified mode consumes a snapshot generated by the canonical SLAI SGEO
 * writer->reader->validation pipeline. Live mode consumes computed geometry
 * in the identical GPU path to avoid serializing an archive every 16ms.
 *
 * This renderer does NOT import SPADRA's BIM-specific ModelView: that class
 * needs the SPADRA Store, project operations, and several unrelated modules.
 * The use of the canonical SGEO API is server-side, where the scene is parsed.
 */
export interface NativeSegment { id:string; start:number[]; end:number[] }
export interface NativeScene {format:'slai.sgeo';source:'canonical_roundtrip'|'canonical_import';valid_native_document:boolean;
    digest_sha256:string;time:number|null;segments:NativeSegment[];mesh?:{vertices:number[][];faces:number[][]}|null}
export interface ViewFrame {geometry:number[][];closed:boolean}
export type Projection = (point:number[],w:number,h:number)=>{x:number;y:number;depth:number};

export class SgeoViewport {
 readonly canvas:HTMLCanvasElement;
 readonly supported:boolean;
 private gl:WebGL2RenderingContext|null;
 private prog:WebGLProgram|null=null;
 private pos=-1;
 private color:WebGLUniformLocation|null=null;
 private buf:WebGLBuffer|null=null;
 private loss=false;
 private maxVerts=130000;
 constructor(canvas:HTMLCanvasElement){
   this.canvas=canvas;
   this.gl=canvas.getContext('webgl2',{antialias:true,alpha:false,preserveDrawingBuffer:false});
   this.supported=!!this.gl;
   if(!this.gl)return;
   this.makeProgram();
   canvas.addEventListener('webglcontextlost',event=>{event.preventDefault();this.loss=true;});
   canvas.addEventListener('webglcontextrestored',()=>{this.loss=false;this.makeProgram();});
 }
 private makeProgram():void {
  const gl=this.gl;if(!gl)return;
  const shader=(type:number,source:string):WebGLShader=>{
   const sh=gl.createShader(type);if(!sh)throw Error('WebGL shader allocation failed');
   gl.shaderSource(sh,source);gl.compileShader(sh);
   if(!gl.getShaderParameter(sh,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(sh)||'WebGL shader compilation failed');
   return sh;
  };
  const vert=shader(gl.VERTEX_SHADER,`#version 300 es
      in vec3 a_position;
      void main() { gl_Position=vec4(a_position,1.0); gl_PointSize=6.0; }`);
  const frag=shader(gl.FRAGMENT_SHADER,`#version 300 es
      precision highp float;uniform vec4 u_color;out vec4 outColor;
      void main(){outColor=u_color;}`);
  const prog=gl.createProgram();if(!prog)throw Error('WebGL program allocation failed');
  gl.attachShader(prog,vert);gl.attachShader(prog,frag);gl.linkProgram(prog);
  if(!gl.getProgramParameter(prog,gl.LINK_STATUS))throw Error(gl.getProgramInfoLog(prog)||'WebGL link failed');
  gl.deleteShader(vert);gl.deleteShader(frag);
  if(this.prog)gl.deleteProgram(this.prog);
  this.prog=prog;this.pos=gl.getAttribLocation(prog,'a_position');
  this.color=gl.getUniformLocation(prog,'u_color');
  if(this.buf)gl.deleteBuffer(this.buf);this.buf=gl.createBuffer();
  gl.enable(gl.BLEND);gl.blendFunc(gl.SRC_ALPHA,gl.ONE_MINUS_SRC_ALPHA);
  gl.disable(gl.CULL_FACE);
 }
 private dimensions():[number,number] {
  const rect=this.canvas.getBoundingClientRect();
  const dpr=Math.min(2,window.devicePixelRatio||1);
  const w=Math.max(1,Math.floor(rect.width*dpr)),h=Math.max(1,Math.floor(rect.height*dpr));
  if(w!==this.canvas.width||h!==this.canvas.height){this.canvas.width=w;this.canvas.height=h;}
  this.gl?.viewport(0,0,w,h);
  return [Math.max(1,rect.width),Math.max(1,rect.height)];
 }
 private drawPositions(points:number[][],type:number,p:Projection,w:number,h:number,
                       rgba:[number,number,number,number],extent:number):void{
  const gl=this.gl;if(!gl||!this.prog||!this.buf||!points.length||points.length>this.maxVerts)return;
  const arr=new Float32Array(points.length*3);
  for(let i=0;i<points.length;i++){
   const v=p(points[i],w,h);
   arr[3*i]=2*v.x/w-1;arr[3*i+1]=1-2*v.y/h;
   arr[3*i+2]=Math.max(-.98,Math.min(.98,v.depth/Math.max(.05,extent*3)));
  }
  gl.useProgram(this.prog);gl.bindBuffer(gl.ARRAY_BUFFER,this.buf);
  gl.bufferData(gl.ARRAY_BUFFER,arr,gl.DYNAMIC_DRAW);
  gl.enableVertexAttribArray(this.pos);gl.vertexAttribPointer(this.pos,3,gl.FLOAT,false,0,0);
  gl.uniform4fv(this.color,rgba);gl.drawArrays(type,0,points.length);
 }
 draw(current:ViewFrame|null,frames:ViewFrame[],projection:Projection,extent:number,
      sheet:boolean,grid:boolean,nativeScene:NativeScene|null=null):void {
   const gl=this.gl;if(!gl||this.loss)return;
   const [w,h]=this.dimensions();
   gl.clearColor(.040,.071,.114,1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);
   gl.enable(gl.DEPTH_TEST);
   if(!current&&!nativeScene)return;
   if(grid){
    const gridLines:number[][]=[];
    const span=Math.max(.1,extent);
    for(let i=-6;i<=6;i++){
     const delta=i*span/6;
     gridLines.push([-span*.6,delta,0],[span*.6,delta,0],
       [delta,-span*.6,0],[delta,span*.6,0]);
    }
    this.drawPositions(gridLines,gl.LINES,projection,w,h,[.18,.39,.5,.27],extent);
   }
   if(nativeScene){
    if(nativeScene.mesh&&nativeScene.mesh.faces.length){
     const tris:number[][]=[];
     const verts=nativeScene.mesh.vertices;
     for(const face of nativeScene.mesh.faces){
      if(face.length<3)continue;
      for(let i=1;i<face.length-1;i++){
       const a=verts[face[0]],b=verts[face[i]],c=verts[face[i+1]];
       if(a&&b&&c)tris.push(a,b,c);
      }
      if(tris.length>this.maxVerts)break;
     }
     gl.depthMask(false);this.drawPositions(tris,gl.TRIANGLES,projection,w,h,[.09,.64,.79,.23],extent);gl.depthMask(true);
    }
    const edges:number[][]=[];
    for(const s of nativeScene.segments){edges.push(s.start,s.end);}
    this.drawPositions(edges,gl.LINES,projection,w,h,[.42,.85,1,1],extent);
    return;
   }
   if(!current)return;
   if(sheet&&frames.length>2){
    const stride=Math.max(1,Math.floor(frames.length/26));
    const columns=Math.max(2,Math.floor(current.geometry.length/32));
    gl.depthMask(false);
    for(let i=0;i<frames.length;i+=stride){
     const path=frames[i].geometry;
     this.drawPositions(path,path.length>1?(frames[i].closed?gl.LINE_LOOP:gl.LINE_STRIP):gl.POINTS,
         projection,w,h,[.14,.58,.77,.19],extent);
    }
    for(let j=0;j<current.geometry.length;j+=columns){
     const trail=frames.filter((_,i)=>i%stride===0).map(f=>f.geometry[j]).filter((v):v is number[]=>!!v);
     this.drawPositions(trail,gl.LINE_STRIP,projection,w,h,[.41,.8,.91,.19],extent);
    }
    gl.depthMask(true);
   }
   const points=current.geometry;
   this.drawPositions(points,points.length>1?(current.closed?gl.LINE_LOOP:gl.LINE_STRIP):gl.POINTS,
     projection,w,h,[.31,.78,.96,1],extent);
   if(!current.closed&&points.length>1){
    this.drawPositions([points[0],points[points.length-1]],gl.POINTS,projection,w,h,[.71,.94,1,1],extent);
   }
 }
}
